cd /tmp; python3 - <<'EOF'
import zipfile, re
z=zipfile.ZipFile('logic.jar')
pat=re.compile(rb'(pkg\.github|maven\.pkg|github\.com|https?://[^\x00-\x1f"]{5,})', re.I)
for n in z.namelist():
    if n.endswith(('.class','.properties','.kts','.txt','.xml','.json')):
        try: d=z.read(n)
        except Exception: continue
        m=set(x.decode(errors='replace') for x in pat.findall(d))
        if m:
            print("==",n)
            for x in sorted(m): print("   ",x)
EOF
